#!/usr/bin/env python3
"""Validation script for pipeline outputs.

Validates:
- outputs/t01_selected_indicators.csv
- outputs/t05_clean_stops.csv
- outputs/t08_pois_clean.csv
- outputs/t10_accessibility_scores.csv
- outputs/t13_city_clusters.csv

Writes results to outputs/t14_validation_summary.json.
"""

import json
import os
import sys

try:
    import pandas as pd
except ImportError:
    print("pandas not found, attempting to install...")
    subprocess_installed = False
    try:
        import subprocess
        subprocess_installed = True
    except ImportError:
        pass
    if subprocess_installed:
        subprocess.check_call(
            [sys.executable, "-m", "pip", "install", "pandas", "-q"],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
        )
    import pandas as pd


def load_csv_safe(filepath):
    """Load a CSV file safely. Returns None if file is missing, empty, or unreadable."""
    if not os.path.exists(filepath):
        return None
    try:
        df = pd.read_csv(filepath)
        if df.empty:
            return None
        return df
    except Exception:
        return None


def load_json_safe(filepath):
    """Load a JSON file safely. Returns None if file is missing or invalid."""
    if not os.path.exists(filepath):
        return None
    try:
        with open(filepath, "r") as f:
            return json.load(f)
    except Exception:
        return None


def check_file_exists_and_not_empty(filepath, prefix):
    """Check that a file exists and is not empty."""
    df = load_csv_safe(filepath)
    if df is None:
        return [
            {
                "check_name": f"{prefix}_exists_and_not_empty",
                "passed": False,
                "message": f"{filepath} is missing or empty",
            }
        ]
    return [
        {
            "check_name": f"{prefix}_exists_and_not_empty",
            "passed": True,
            "message": f"{filepath} exists and contains data ({len(df)} rows)",
        }
    ]


def check_expected_columns(filepath, expected_cols, prefix):
    """Check that a CSV file contains all expected columns."""
    df = load_csv_safe(filepath)
    if df is None:
        return [
            {
                "check_name": f"{prefix}_expected_columns",
                "passed": False,
                "message": f"Cannot check columns: {filepath} is missing or empty",
            }
        ]
    missing = [c for c in expected_cols if c not in df.columns]
    if missing:
        return [
            {
                "check_name": f"{prefix}_expected_columns",
                "passed": False,
                "message": f"Missing columns in {filepath}: {missing}",
            }
        ]
    return [
        {
            "check_name": f"{prefix}_expected_columns",
            "passed": True,
            "message": f"All expected columns present in {filepath}",
        }
    ]


def check_row_count(filepath, expected_count, prefix):
    """Check that a CSV file has the expected number of rows."""
    df = load_csv_safe(filepath)
    if df is None:
        return [
            {
                "check_name": f"{prefix}_row_count",
                "passed": False,
                "message": f"Cannot check row count: {filepath} is missing or empty",
            }
        ]
    actual = len(df)
    if actual != expected_count:
        return [
            {
                "check_name": f"{prefix}_row_count",
                "passed": False,
                "message": f"Expected {expected_count} rows in {filepath}, found {actual}",
            }
        ]
    return [
        {
            "check_name": f"{prefix}_row_count",
            "passed": True,
            "message": f"{filepath} has expected {expected_count} rows",
        }
    ]


def check_no_nulls(filepath, columns, prefix):
    """Check that specified columns have no null values."""
    df = load_csv_safe(filepath)
    if df is None:
        return [
            {
                "check_name": f"{prefix}_no_nulls",
                "passed": False,
                "message": f"Cannot check nulls: {filepath} is missing or empty",
            }
        ]
    null_counts = {col: int(df[col].isna().sum()) for col in columns if col in df.columns}
    null_cols = {k: v for k, v in null_counts.items() if v > 0}
    if null_cols:
        return [
            {
                "check_name": f"{prefix}_no_nulls",
                "passed": False,
                "message": f"Null values found in {filepath}: {null_cols}",
            }
        ]
    return [
        {
            "check_name": f"{prefix}_no_nulls",
            "passed": True,
            "message": f"No null values in key columns of {filepath}",
        }
    ]


def check_numeric_positive(filepath, columns, prefix):
    """Check that specified numeric columns contain only non-negative values."""
    df = load_csv_safe(filepath)
    if df is None:
        return [
            {
                "check_name": f"{prefix}_numeric_positive",
                "passed": False,
                "message": f"Cannot check numeric values: {filepath} is missing or empty",
            }
        ]
    issues = []
    for col in columns:
        if col in df.columns and pd.api.types.is_numeric_dtype(df[col]):
            neg_count = int((df[col] < 0).sum())
            if neg_count > 0:
                issues.append(f"{col} has {neg_count} negative values")
    if issues:
        return [
            {
                "check_name": f"{prefix}_numeric_positive",
                "passed": False,
                "message": f"Issues in {filepath}: {'; '.join(issues)}",
            }
        ]
    return [
        {
            "check_name": f"{prefix}_numeric_positive",
            "passed": True,
            "message": f"All numeric columns in {filepath} are non-negative",
        }
    ]


def validate_outputs():
    """Run all validation checks and return results list."""
    results = []

    # ---- t01: selected indicators ----
    results.extend(check_file_exists_and_not_empty("outputs/t01_selected_indicators.csv", "t01"))
    results.extend(
        check_expected_columns(
            "outputs/t01_selected_indicators.csv",
            ["indicator_id", "indicator_name", "theme", "justification", "expected_direction"],
            "t01",
        )
    )
    results.extend(check_row_count("outputs/t01_selected_indicators.csv", 12, "t01"))
    results.extend(
        check_no_nulls(
            "outputs/t01_selected_indicators.csv",
            ["indicator_id", "indicator_name"],
            "t01",
        )
    )

    # ---- t05: clean stops ----
    results.extend(check_file_exists_and_not_empty("outputs/t05_clean_stops.csv", "t05"))
    results.extend(
        check_expected_columns(
            "outputs/t05_clean_stops.csv",
            ["stop_id", "stop_name", "stop_lat", "stop_lon"],
            "t05",
        )
    )
    results.extend(check_row_count("outputs/t05_clean_stops.csv", 407, "t05"))
    results.extend(
        check_numeric_positive(
            "outputs/t05_clean_stops.csv",
            ["stop_lat", "stop_lon"],
            "t05",
        )
    )

    # ---- t08: POIs clean ----
    results.extend(check_file_exists_and_not_empty("outputs/t08_pois_clean.csv", "t08"))
    results.extend(
        check_expected_columns(
            "outputs/t08_pois_clean.csv",
            ["qid", "label", "poi_type", "latitude", "longitude", "source"],
            "t08",
        )
    )
    results.extend(check_row_count("outputs/t08_pois_clean.csv", 48, "t08"))
    results.extend(
        check_no_nulls(
            "outputs/t08_pois_clean.csv",
            ["qid", "poi_type"],
            "t08",
        )
    )

    # ---- t10: accessibility scores ----
    results.extend(check_file_exists_and_not_empty("outputs/t10_accessibility_scores.csv", "t10"))
    results.extend(
        check_expected_columns(
            "outputs/t10_accessibility_scores.csv",
            ["qid", "label", "poi_type", "distance_m", "n_departures", "n_routes", "accessibility_score"],
            "t10",
        )
    )
    results.extend(check_row_count("outputs/t10_accessibility_scores.csv", 48, "t10"))
    results.extend(
        check_no_nulls(
            "outputs/t10_accessibility_scores.csv",
            ["qid", "accessibility_score"],
            "t10",
        )
    )

    # ---- t13: city clusters ----
    results.extend(check_file_exists_and_not_empty("outputs/t13_city_clusters.csv", "t13"))
    results.extend(
        check_expected_columns(
            "outputs/t13_city_clusters.csv",
            ["city_id", "cluster_id"],
            "t13",
        )
    )
    results.extend(
        check_no_nulls(
            "outputs/t13_city_clusters.csv",
            ["city_id", "cluster_id"],
            "t13",
        )
    )

    return results


def main():
    """Entry point: run validation and write summary."""
    results = validate_outputs()

    # Ensure output directory exists
    os.makedirs("outputs", exist_ok=True)

    with open("outputs/t14_validation_summary.json", "w") as f:
        json.dump(results, f, indent=2)

    passed = sum(1 for r in results if r["passed"])
    failed = sum(1 for r in results if not r["passed"])
    total = len(results)

    print(f"Validation complete: {passed}/{total} checks passed, {failed} failed")
    for r in results:
        status = "PASS" if r["passed"] else "FAIL"
        print(f"  [{status}] {r['check_name']}: {r['message']}")

    if failed > 0:
        sys.exit(1)


if __name__ == "__main__":
    main()
