        return None
    try:
        df = pd.read_csv(filepath)
        if df.empty:
            return None
        return df
    except Exception:
        return None


def load_json_safe(filepath):
    """Load a JSON file safely. Returns None if file is missing or invalid."""
    if not os.path.exists(filepath):
        return None
    try:
        with open(filepath, "r") as f:
            return json.load(f)
    except Exception:
        return None


def check_file_exists_and_not_empty(filepath, prefix):
    """Check that a file exists and is not empty."""
    df = load_csv_safe(filepath)
