def check_no_nulls(filepath, columns, prefix):
    """Check that specified columns have no null values."""
    df = load_csv_safe(filepath)
    if df is None:
        return [
            {
                "check_name": f"{prefix}_no_nulls",
                "passed": False,
                "message": f"Cannot check nulls: {filepath} is missing or empty",
            }
        ]
    null_counts = {col: int(df[col].isna().sum()) for col in columns if col in df.columns}
    null_cols = {k: v for k, v in null_counts.items() if v > 0}
    if null_cols:
        return [
            {
                "check_name": f"{prefix}_no_nulls",
                "passed": False,
                "message": f"Null values found in {filepath}: {null_cols}",
            }
        ]
    return [
        {
            "check_name": f"{prefix}_no_nulls",
            "passed": True,
            "message": f"No null values in key columns of {filepath}",
        }
    ]


def check_numeric_positive(filepath, columns, prefix):
    """Check that specified numeric columns contain only non-negative values."""
    df = load_csv_safe(filepath)
    if df is None:
        return [
            {
                "check_name": f"{prefix}_numeric_positive",
                "passed": False,
                "message": f"Cannot check numeric values: {filepath} is missing or empty",
            }
        ]
    issues = []
    for col in columns:
        if col in df.columns and pd.api.types.is_numeric_dtype(df[col]):
            neg_count = int((df[col] < 0).sum())
            if neg_count > 0:
                issues.append(f"{col} has {neg_count} negative values")
    if issues:
        return [
            {
                "check_name": f"{prefix}_numeric_positive",
                "passed": False,
                "message": f"Issues in {filepath}: {'; '.join(issues)}",
            }
        ]
    return [
        {
            "check_name": f"{prefix}_numeric_positive",
            "passed": True,
            "message": f"All numeric columns in {filepath} are non-negative",
        }
    ]


